4	export async function getCustomerOrders() {
5	  const user = await getCurrentUser();
6	  if (!user) {
7	    throw new Error("Non autorisé. Veuillez vous connecter.");
8	  }
9	
10	  return await prisma.order.findMany({
11	    where: { userId: user.id },
12	    include: {
13	      items: {
14	        include: {
15	          product: true,
16	          variant: true,
17	        },
18	      },
19	    },
20	    orderBy: { createdAt: "desc" },
21	  });
22	}
