24	export async function getCustomerOrderById(orderId: string) {
25	  const user = await getCurrentUser();
26	  if (!user) {
27	    throw new Error("Non autorisé. Veuillez vous connecter.");
28	  }
29	
30	  const order = await prisma.order.findUnique({
31	    where: { id: orderId },
32	    include: {
33	      items: {
34	        include: {
35	          product: true,
36	          variant: true,
37	        },
38	      },
39	    },
40	  });
41	
42	  if (!order || (order.userId !== user.id && user.role !== "ADMIN")) {
43	    throw new Error("Commande introuvable ou accès non autorisé");
44	  }
45	
46	  return order;
47	}
